function render(){const u=currentUser();if(!u)return renderPublic();const c=currentCompany();if(!c)return renderPublic();renderApp()}
function renderPublic(){
  app.innerHTML=`<div class="landing"><header class="landing-nav container"><div class="brand"><span class="brandmark" aria-label="Logo CIA">CIA</span><span>CIA</span></div><nav><button class="btn ghost" onclick="location.hash='#login'">Entrar</button><button class="btn primary" onclick="location.hash='#register'">Crear cuenta</button></nav></header><main class="hero container"><div class="hero-copy"><span class="eyebrow">PLATAFORMA DE GESTIÓN EMPRESARIAL</span><h1>Todo tu negocio,<br><em>conectado.</em></h1><p>Ventas, clientes, inventario, compras, finanzas, equipo y sucursales en una sola plataforma clara y modular.</p><div class="hero-actions"><button class="btn primary big" onclick="enterSampleWorkspace()">Explorar prototipo</button><button class="btn secondary big" onclick="location.hash='#register'">Crear una empresa</button></div><div class="hero-proof"><span>✓ Sin instalación</span><span>✓ Multiusuario</span><span>✓ Modular</span></div></div><div class="hero-product"><div class="mock-top"><span></span><span></span><span></span><small>Resumen ejecutivo</small></div><div class="mock-kpis"><div><small>Ingresos</small><strong>$184,520</strong><b>+18.4%</b></div><div><small>Utilidad</small><strong>$62,840</strong><b>34.1%</b></div><div><small>Por cobrar</small><strong>$35,760</strong><b class="warn">4 cuentas</b></div></div><div class="mock-chart">${[38,49,45,60,68,77,88].map((h,i)=>`<span style="height:${h}%"><i></i><small>${['M','A','M','J','J','A','S'][i]}</small></span>`).join('')}</div><div class="mock-row"><strong>Centro operativo</strong><span>2 autorizaciones</span><span>2 alertas</span><span>3 tareas</span></div></div></main><section class="landing-features"><div class="container"><div class="section-head"><span class="eyebrow dark">UNA SOLA SUITE</span><h2>Hecha para operar, no para complicar.</h2></div><div class="feature-grid">${[['01','Comercial','Cotizaciones, pedidos, ventas, clientes y seguimiento.'],['02','Operación','Inventario, compras, proveedores, transferencias y alertas.'],['03','Finanzas','Caja, bancos, cuentas por cobrar/pagar y flujo.'],['04','Gestión','Equipo, permisos, sucursales, tareas y autorizaciones.'],['05','Análisis','KPIs, tendencias, reportes y exportaciones.'],['06','Control','Bitácora, roles y trazabilidad de decisiones.']].map(x=>`<article><span>${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div></div></section></div>`;
  if(location.hash==='#login')renderLogin();if(location.hash==='#register')renderRegister();
}
function authShell(title,sub,body){app.innerHTML=`<div class="auth"><section class="auth-side"><div class="brand"><span class="brandmark" aria-label="Logo CIA">CIA</span>CIA</div><div><span class="eyebrow">TODO TU NEGOCIO, CONECTADO</span><h2>Una base lista para crecer contigo.</h2><p>Configura tu empresa, crea usuarios, asigna permisos y empieza a operar desde un solo espacio.</p><button class="demo-link" onclick="enterSampleWorkspace()">→ Explorar espacio de ejemplo</button></div><small>Prototipo funcional · sin persistencia</small></section><section class="auth-main"><div class="auth-card"><h1>${title}</h1><p>${sub}</p>${body}<button class="link" onclick="location.hash=''">← Volver al inicio</button></div></section></div>`}
function renderLogin(){authShell('Iniciar sesión','Accede a tu espacio de trabajo.',`<form id="loginForm" class="form"><label>Correo<input name="email" type="email" required></label><label>Contraseña<input name="password" type="password" required></label><button class="btn primary">Entrar</button><div id="authMsg"></div></form><div class="auth-switch">¿No tienes cuenta? <button class="link" onclick="location.hash='#register'">Crear cuenta</button></div>`);document.getElementById('loginForm').onsubmit=loginSubmit}
function renderRegister(){authShell('Crear empresa','Crea al propietario y tu espacio de trabajo.',`<form id="registerForm" class="form"><label>Nombre completo<input name="name" required></label><label>Empresa<input name="company" required></label><label>Correo<input name="email" type="email" required></label><div class="two"><label>Contraseña<input name="password" type="password" minlength="6" required></label><label>Confirmar<input name="confirm" type="password" minlength="6" required></label></div><button class="btn primary">Crear cuenta y empresa</button><div id="authMsg"></div></form><div class="auth-switch">¿Ya tienes cuenta? <button class="link" onclick="location.hash='#login'">Iniciar sesión</button></div>`);document.getElementById('registerForm').onsubmit=registerSubmit}
async function enterSampleWorkspace(){const u=seedSampleWorkspace();setSession({userId:u.id,companyId:'cmp_sample',sample:true});location.hash='';ui.route='dashboard';render()}
async function loginSubmit(e){e.preventDefault();const f=new FormData(e.target),email=f.get('email').trim().toLowerCase();if(email===SAMPLE_EMAIL)return enterSampleWorkspace();const ph=await hashPassword(f.get('password'));const db=loadDB(),u=db.users.find(x=>x.email===email&&x.passwordHash===ph);if(!u)return document.getElementById('authMsg').innerHTML='<div class="error">Correo o contraseña incorrectos.</div>';setSession({userId:u.id,companyId:u.companyIds?.[0]});location.hash='';render()}
async function registerSubmit(e){e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim(),company=f.get('company').trim(),email=f.get('email').trim().toLowerCase(),p=f.get('password');if(p!==f.get('confirm'))return document.getElementById('authMsg').innerHTML='<div class="error">Las contraseñas no coinciden.</div>';const db=loadDB();if(db.users.some(u=>u.email===email))return document.getElementById('authMsg').innerHTML='<div class="error">Ese correo ya está registrado.</div>';const uidu=uid('usr'),cid=uid('cmp'),rid=uid('role');db.users.push({id:uidu,name,email,passwordHash:await hashPassword(p),companyIds:[cid],createdAt:nowISO()});db.companies.push({id:cid,name:company,legalName:company,rfc:'',currency:'MXN',tax:16,plan:'Prototipo',branches:[{id:uid('br'),name:'Principal',city:'',address:'',active:true}],roles:[{id:rid,name:'Propietario',permissions:[...PERMISSIONS],system:true}],members:[{userId:uidu,roleId:rid,status:'active'}],data:{products:[],customers:[],suppliers:[],sales:[],quotes:[],orders:[],purchases:[],accounts:[],transactions:[],tasks:[],approvals:[],audit:[],notifications:[],metrics:{revenue:0,profit:0,expenses:0,receivable:0,payable:0,inventoryValue:0,margin:0,monthGrowth:0},trend:[0,0,0,0,0,0,0],branchSales:[],categorySales:[]}});saveDB(db);setSession({userId:uidu,companyId:cid});location.hash='';render()}

function renderApp(){const c=currentCompany(),u=currentUser(),r=role();if(!can(ui.route))ui.route='dashboard';const unread=(data().notifications||[]).filter(n=>!n.read).length;app.innerHTML=`<div class="shell ${ui.mobileMenu?'mobile-menu-open':''}"><div class="mobile-backdrop" onclick="ui.mobileMenu=false;renderApp()"></div><aside class="sidebar"><div class="side-brand"><div class="brand"><span class="brandmark" aria-label="Logo CIA">CIA</span><span class="brandtext">CIA</span></div><button class="collapse">‹</button><button class="mobile-close" onclick="ui.mobileMenu=false;renderApp()">×</button></div><div class="company-switch"><div><strong>${esc(c.name)}</strong><small>${esc(c.plan||'Prototipo')}</small></div><span>⌄</span></div><nav>${NAV.map(([grp,items])=>{const visible=items.filter(x=>can(x[0]));return visible.length?`<section><small>${grp}</small>${visible.map(([route,label,icon])=>`<button class="nav-item ${ui.route===route?'active':''}" onclick="go('${route}')"><i>${icon}</i><span>${label}</span>${route==='approvals'&&data().approvals?.filter(x=>x.status==='pending').length?`<b>${data().approvals.filter(x=>x.status==='pending').length}</b>`:''}</button>`).join('')}</section>`:''}).join('')}</nav><div class="side-user"><div class="avatar">${initials(u.name)}</div><div><strong>${esc(u.name)}</strong><small>${esc(r?.name||'Usuario')}</small></div><button onclick="logout()">↪</button></div></aside><main class="main"><header class="appbar"><button class="mobile-menu-btn" onclick="ui.mobileMenu=true;renderApp()" aria-label="Abrir menú">☰</button><button class="search" onclick="ui.command=true;renderApp()">⌕ <span>Buscar en CIA</span><kbd>Ctrl K</kbd></button><div class="prototype-flag">GUARDADO EN ESTE NAVEGADOR · datos locales</div><div class="app-actions"><select onchange="ui.branch=this.value;renderApp()"><option value="all">Todas las sucursales</option>${c.branches.map(b=>`<option ${ui.branch===b.name?'selected':''}>${esc(b.name)}</option>`).join('')}</select><button class="icon-btn ${unread?'dot':''}" onclick="ui.notifs=!ui.notifs;renderApp()">◌</button><button class="btn primary small" onclick="quickCreate()">＋ Crear</button></div></header><div class="page">${renderPage()}</div></main>${ui.notifs?renderNotifications():''}${ui.command?renderCommand():''}${ui.modal?renderModal():''}${ui.toast?`<div class="toast">✓ ${esc(ui.toast)}</div>`:''}</div>`;bindCharts()}
function go(r){ui.route=r;ui.command=false;ui.notifs=false;renderApp()}
function logout(){setSession(null);location.hash='';render()}
function quickCreate(){const map={dashboard:'sale',sales:'sale',quotes:'quote',orders:'order',customers:'customer',products:'product',inventory:'product',purchases:'purchase',suppliers:'supplier',finance:'transaction',tasks:'task',users:'user',branches:'branch',roles:'role'};openModal(map[ui.route]||'task')}
function pageHead(title,sub,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div><div class="head-actions">${actions}</div></div>`}
function kpi(label,val,meta='',tone=''){return `<div class="kpi ${tone}"><div><small>${label}</small><strong>${val}</strong></div><span>${meta}</span></div>`}
function renderPage(){switch(ui.route){case'dashboard':return dashboard();case'sales':return entityPage('Ventas','Seguimiento de ventas y cobranza.','sales');case'quotes':return entityPage('Cotizaciones','Propuestas comerciales y seguimiento.','quotes');case'orders':return entityPage('Pedidos','Pedidos aceptados y preparación.','orders');case'customers':return customersPage();case'products':return productsPage();case'inventory':return inventoryPage();case'purchases':return entityPage('Compras','Órdenes, recepción y cuentas por pagar.','purchases');case'suppliers':return suppliersPage();case'finance':return financePage();case'tasks':return tasksPage();case'approvals':return approvalsPage();case'reports':return reportsPage();case'users':return usersPage();case'branches':return branchesPage();case'audit':return auditPage();case'roles':return rolesPage();case'settings':return settingsPage();default:return dashboard()}}
function dashboard(){const d=data(),m=d.metrics;const low=d.products.filter(p=>p.type==='Producto'&&p.stock<=p.minStock);const overdue=d.customers.filter(c=>c.balance>0);const pendAp=d.approvals.filter(a=>a.status==='pending');const pendingTasks=d.tasks.filter(t=>t.status!=='done');return `${pageHead('Resumen ejecutivo','Así está operando tu empresa hoy.',`<div class="periods">${['Hoy','Semana','Mes','Año'].map(p=>`<button class="${ui.period===p?'active':''}" onclick="ui.period='${p}';renderApp()">${p}</button>`).join('')}</div>`)}<div class="kpi-grid">${kpi('Ingresos',money(m.revenue),`↑ ${pct(m.monthGrowth)} vs mes anterior`,'good')}${kpi('Utilidad',money(m.profit),`${pct(m.margin)} de margen`)}${kpi('Gastos',money(m.expenses),'Operación del periodo')}${kpi('Por cobrar',money(m.receivable),`${overdue.length} cuentas abiertas`,'warn')}${kpi('Por pagar',money(m.payable),'Proveedores')}${kpi('Inventario',money(m.inventoryValue),`${low.length} alertas de stock`)}</div><div class="dashboard-grid"><section class="card chart-card"><div class="card-head"><div><h3>Ingresos del negocio</h3><p>Últimos 7 periodos</p></div><span class="badge success">+18.4%</span></div><div class="line-chart" id="lineChart"></div></section><section class="card attention"><div class="card-head"><div><h3>Centro operativo</h3><p>Lo que necesita atención</p></div></div><button onclick="go('approvals')"><span class="attention-icon warning">◆</span><div><strong>${pendAp.length} autorizaciones</strong><small>Esperan una decisión</small></div><b>→</b></button><button onclick="go('inventory')"><span class="attention-icon danger">▤</span><div><strong>${low.length} alertas de inventario</strong><small>Productos bajo mínimo</small></div><b>→</b></button><button onclick="go('tasks')"><span class="attention-icon info">✓</span><div><strong>${pendingTasks.length} tareas abiertas</strong><small>Equipo y pendientes</small></div><b>→</b></button><button onclick="go('customers')"><span class="attention-icon teal">◎</span><div><strong>${overdue.length} cuentas por cobrar</strong><small>${money(m.receivable)} pendientes</small></div><b>→</b></button></section></div><div class="dashboard-grid thirds"><section class="card"><div class="card-head"><div><h3>Ventas por sucursal</h3><p>Participación del periodo</p></div></div>${d.branchSales.map(x=>`<div class="progress-row"><div><strong>${x.name}</strong><span>${money(x.value)}</span></div><div class="progress"><i style="width:${Math.round(x.value/m.revenue*100)}%"></i></div></div>`).join('')}</section><section class="card"><div class="card-head"><div><h3>Últimas ventas</h3><p>Actividad comercial</p></div><button class="link" onclick="go('sales')">Ver todas</button></div>${d.sales.slice(0,4).map(s=>`<div class="mini-row"><div><strong>${s.customer}</strong><small>${s.folio} · ${fmtShort(s.createdAt)}</small></div><b>${money(s.total)}</b></div>`).join('')}</section><section class="card"><div class="card-head"><div><h3>Actividad reciente</h3><p>Quién hizo qué</p></div><button class="link" onclick="go('audit')">Bitácora</button></div>${d.audit.slice(0,4).map(a=>`<div class="activity-row"><span>${initials(a.user)}</span><div><strong>${a.action}</strong><small>${a.user} · ${fmtShort(a.at)}</small></div></div>`).join('')}</section></div>`}
function entityPage(title,sub,type){const rows=type==='inventoryMovements'?(data().inventoryMovements||[]):(data()[type]||[]);const cfg={sales:{button:'Nueva venta',modal:'sale'},quotes:{button:'Nueva cotización',modal:'quote'},orders:{button:'Nuevo pedido',modal:'order'},purchases:{button:'Nueva compra',modal:'purchase'}}[type];return `${pageHead(title,sub,`<button class="btn secondary" onclick="exportCSV('${type}')">Exportar</button><button class="btn primary" onclick="openModal('${cfg.modal}')">＋ ${cfg.button}</button>`)}<section class="card table-card"><div class="table-tools"><input placeholder="Buscar en ${title.toLowerCase()}…" oninput="filterTable(this,'${type}')"><select><option>Todos los estados</option><option>Pendientes</option><option>Completados</option></select></div><div class="table-wrap"><table id="tbl_${type}">${entityHeader(type)}<tbody>${rows.map(r=>entityRow(type,r)).join('')}</tbody></table></div></section>`}
function entityHeader(t){const heads={sales:['Folio','Cliente','Concepto','Sucursal','Estado','Total'],quotes:['Folio','Cliente','Concepto','Vigencia','Estado','Total'],orders:['Folio','Cliente','Concepto','Estado','Total',''],purchases:['Folio','Proveedor','Concepto','Entrega','Estado','Total']}[t];return `<thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead>`}
function status(s){const map={paid:['Pagada','success'],partial:['Pago parcial','warning'],confirmed:['Confirmada','info'],pending:['Pendiente','warning'],draft:['Borrador','muted'],sent:['Enviada','info'],accepted:['Aceptada','success'],preparing:['Preparando','info'],ready:['Lista','success'],ordered:['Ordenada','info'],received:['Recibida','success']};const [l,c]=map[s]||[s,'muted'];return `<span class="badge ${c}">${l}</span>`}
function entityRow(t,r){if(t==='sales')return `<tr><td><strong>${esc(r.folio)}</strong></td><td>${esc(r.customer)}</td><td>${esc(r.concept||`${(r.items||[]).length} producto(s)`)}</td><td>${esc(r.branch||'—')}</td><td>${status(r.paymentStatus||r.status)}</td><td><strong>${money(r.total)}</strong>${r.balance>0?`<small>Saldo ${money(r.balance)}</small>`:''}</td></tr>`;if(t==='quotes')return `<tr><td><strong>${r.folio}</strong></td><td>${r.customer}</td><td>${r.concept}</td><td>${r.validUntil?fmtShort(r.validUntil):'—'}</td><td>${status(r.status)}</td><td><strong>${money(r.total)}</strong>${r.status==='accepted'?`<button class="tiny" onclick="convertQuote('${r.id}')">→ pedido</button>`:''}</td></tr>`;if(t==='orders')return `<tr><td><strong>${r.folio}</strong></td><td>${r.customer}</td><td>${r.concept}</td><td>${status(r.status)}</td><td><strong>${money(r.total)}</strong></td><td><button class="tiny">Ver</button></td></tr>`;return `<tr><td><strong>${r.folio}</strong></td><td>${r.supplier}</td><td>${r.concept}</td><td>${r.expected?fmtShort(r.expected):'—'}</td><td>${status(r.status)}</td><td><strong>${money(r.total)}</strong></td></tr>`}
function filterTable(inp,type){const q=inp.value.toLowerCase();document.querySelectorAll(`#tbl_${type} tbody tr`).forEach(tr=>tr.style.display=tr.innerText.toLowerCase().includes(q)?'':'none')}
function customersPage(){const rows=data().customers;return `${pageHead('Clientes','Relaciones comerciales, crédito y cobranza.',`<button class="btn secondary" onclick="exportCSV('customers')">Exportar</button><button class="btn primary" onclick="openModal('customer')">＋ Nuevo cliente</button>`)}<div class="summary-strip"><div><small>Clientes activos</small><strong>${rows.length}</strong></div><div><small>Cartera total</small><strong>${money(rows.reduce((a,b)=>a+b.balance,0))}</strong></div><div><small>Ventas acumuladas</small><strong>${money(rows.reduce((a,b)=>a+b.sales,0))}</strong></div></div><div class="cards-grid">${rows.map(c=>`<article class="entity-card" onclick="showCustomer('${c.id}')"><div class="entity-head"><span class="entity-avatar">${initials(c.name)}</span><div><h3>${c.name}</h3><small>${c.rfc}</small></div><span class="badge success">${c.status}</span></div><div class="entity-metrics"><div><small>Saldo</small><strong>${money(c.balance)}</strong></div><div><small>Límite</small><strong>${money(c.creditLimit)}</strong></div><div><small>Ventas</small><strong>${money(c.sales)}</strong></div></div><div class="entity-foot"><span>${c.seller}</span><b>Ver ficha →</b></div></article>`).join('')}</div>`}
function showCustomer(id){const c=data().customers.find(x=>x.id===id);ui.modal={type:'customerView',id};renderApp()}
function productsPage(){const rows=data().products;return `${pageHead('Productos y servicios','Catálogo, costos, precios y rentabilidad.',`<button class="btn secondary" onclick="exportCSV('products')">Exportar</button><button class="btn primary" onclick="openModal('product')">＋ Nuevo producto</button>`)}<section class="card table-card"><div class="table-tools"><input placeholder="Buscar producto, SKU o categoría…" oninput="filterTable(this,'products')"><select><option>Todas las categorías</option>${[...new Set(rows.map(x=>x.category))].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="table-wrap"><table id="tbl_products"><thead><tr><th>Producto / servicio</th><th>SKU</th><th>Categoría</th><th>Precio</th><th>Costo</th><th>Margen</th><th>Existencia</th></tr></thead><tbody>${rows.map(p=>`<tr onclick="showProduct('${p.id}')"><td><strong>${p.name}</strong><small>${p.type}</small></td><td>${p.sku}</td><td>${p.category}</td><td>${money(p.price)}</td><td>${money(p.cost)}</td><td><strong>${p.cost?pct((p.price-p.cost)/p.price*100):'100%'}</strong></td><td>${p.type==='Producto'?`<span class="stock ${p.stock<=p.minStock?'low':''}">${p.stock}</span>`:'—'}</td></tr>`).join('')}</tbody></table></div></section>`}
function showProduct(id){ui.modal={type:'productView',id};renderApp()}
function inventoryPage(){const p=data().products.filter(x=>x.type==='Producto');const moves=(data().inventoryMovements||[]).slice(0,8);const low=p.filter(x=>Number(x.stock)<=Number(x.minStock));const total=p.reduce((sum,x)=>sum+Number(x.stock||0)*Number(x.cost||0),0);return `${pageHead('Inventario','Control de existencias, ajustes y movimientos.',`<button class="btn secondary" onclick="openModal('stockCount')">Conteo físico</button><button class="btn primary" onclick="openModal('stockAdjustment')">＋ Movimiento de stock</button>`)}<div class="kpi-grid inventory-kpis">${kpi('Productos',p.length,'Con control de existencias')}${kpi('Valor del inventario',money(total),'Valuado al costo')}${kpi('Stock bajo',low.length,low.length?'Requiere revisión':'Sin alertas',low.length?'warn':'good')}</div><div class="inventory-cards">${p.map(x=>{const max=Math.max(1,Number(x.maxStock)||100);return `<article class="card inv-card"><div class="inv-top"><div><h3>${esc(x.name)}</h3><small>${esc(x.sku||'Sin SKU')} · ${esc(x.category||'General')}</small></div>${Number(x.stock)<=Number(x.minStock)?'<span class="badge danger">Stock bajo</span>':'<span class="badge success">Normal</span>'}</div><div class="inv-numbers"><div><small>Existencia</small><strong>${Number(x.stock)||0}</strong></div><div><small>Comprometido</small><strong>${Number(x.reserved)||0}</strong></div><div><small>En camino</small><strong>${Number(x.incoming)||0}</strong></div><div><small>Mínimo</small><strong>${Number(x.minStock)||0}</strong></div></div><div class="progress"><i style="width:${Math.min(100,Math.round((Number(x.stock)||0)/max*100))}%"></i></div><div class="inv-foot"><span>Valor al costo: ${money((Number(x.stock)||0)*(Number(x.cost)||0))}</span><button class="tiny" onclick="showProduct('${x.id}')">Ver ficha</button><button class="tiny" onclick="openStockAdjustment('${x.id}')">Ajustar</button></div></article>`}).join('')||'<div class="empty-state">No hay productos con control de stock. Crea un producto para comenzar.</div>'}</div><section class="card table-card inventory-movements"><div class="card-head"><div><h3>Movimientos recientes</h3><p>Entradas, salidas, ajustes y ventas</p></div><button class="btn secondary small" onclick="exportCSV('inventoryMovements')">Exportar</button></div><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Producto</th><th>Movimiento</th><th>Cantidad</th><th>Referencia</th><th>Usuario</th></tr></thead><tbody>${moves.map(m=>`<tr><td>${fmtShort(m.at||m.createdAt)}</td><td><strong>${esc(m.product||p.find(x=>x.id===m.productId)?.name||'Producto eliminado')}</strong></td><td>${esc(({sale:'Venta',purchase:'Entrada por compra',in:'Entrada',out:'Salida',adjustment:'Ajuste',count:'Conteo físico'})[m.type]||m.type||'Movimiento')}</td><td><span class="${Number(m.quantity)<0?'stock low':'stock'}">${Number(m.quantity)>0?'+':''}${Number(m.quantity)||0}</span></td><td>${esc(m.reference||'—')}</td><td>${esc(m.user||'—')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty-cell">Aún no hay movimientos registrados.</td></tr>'}</tbody></table></div></section>`}
function openStockAdjustment(productId=''){ui.modal={type:'stockAdjustment',productId};renderApp()}
function suppliersPage(){const rows=data().suppliers;return `${pageHead('Proveedores','Compras, saldos y relación de suministro.',`<button class="btn primary" onclick="openModal('supplier')">＋ Nuevo proveedor</button>`)}<div class="cards-grid">${rows.map(s=>`<article class="entity-card"><div class="entity-head"><span class="entity-avatar supplier">${initials(s.name)}</span><div><h3>${s.name}</h3><small>${s.rfc}</small></div></div><div class="entity-metrics"><div><small>Saldo</small><strong>${money(s.balance)}</strong></div><div><small>Última compra</small><strong>${fmtShort(s.lastPurchase)}</strong></div></div><div class="entity-foot"><span>${s.email}</span><b>Ver proveedor →</b></div></article>`).join('')}</div>`}
function financePage(){const d=data(),m=d.metrics;return `${pageHead('Caja y bancos','Liquidez, movimientos y posición financiera.',`<button class="btn secondary" onclick="openModal('account')">＋ Cuenta</button><button class="btn primary" onclick="openModal('transaction')">＋ Movimiento</button>`)}<div class="finance-grid"><section class="account-list">${d.accounts.map(a=>`<article class="account-card"><span>${a.type==='bank'?'▰':'▣'}</span><div><small>${a.type==='bank'?'Cuenta bancaria':'Efectivo'}</small><h3>${a.name}</h3><strong>${money(a.balance)}</strong></div></article>`).join('')}<article class="account-card total"><span>Σ</span><div><small>Liquidez disponible</small><h3>Total cuentas</h3><strong>${money(d.accounts.reduce((a,b)=>a+b.balance,0))}</strong></div></article></section><section class="card"><div class="card-head"><div><h3>Flujo reciente</h3><p>Últimos movimientos</p></div></div>${d.transactions.map(t=>`<div class="transaction"><span class="${t.kind}">${t.kind==='income'?'↓':'↑'}</span><div><strong>${t.concept}</strong><small>${fmtShort(t.at)} · ${d.accounts.find(a=>a.id===t.accountId)?.name||''}</small></div><b class="${t.kind}">${t.kind==='expense'?'-':'+'}${money(t.amount)}</b></div>`).join('')}</section></div><div class="kpi-grid finance-kpis">${kpi('Por cobrar',money(m.receivable),'Clientes')}${kpi('Por pagar',money(m.payable),'Proveedores')}${kpi('Gastos del periodo',money(m.expenses),'Operación')}${kpi('Utilidad',money(m.profit),pct(m.margin),'good')}</div>`}
function tasksPage(){const rows=data().tasks;return `${pageHead('Tareas','Pendientes operativos y responsables.',`<button class="btn primary" onclick="openModal('task')">＋ Nueva tarea</button>`)}<div class="kanban">${[['pending','Por hacer'],['in_progress','En proceso'],['done','Completadas']].map(([s,l])=>`<section><header><h3>${l}</h3><span>${rows.filter(x=>x.status===s).length}</span></header>${rows.filter(x=>x.status===s).map(t=>`<article><div><span class="priority ${t.priority.toLowerCase()}">${t.priority}</span><h4>${t.title}</h4><p>${t.assignee}</p></div><footer><small>${t.due?fmtShort(t.due):'Sin fecha'}</small>${s!=='done'?`<button class="tiny" onclick="completeTask('${t.id}')">Completar</button>`:'✓'}</footer></article>`).join('')||'<div class="empty-mini">Sin tareas</div>'}</section>`).join('')}</div>`}
function approvalsPage(){const rows=data().approvals;return `${pageHead('Autorizaciones','Decisiones que requieren un nivel superior.',``)}<div class="approval-list">${rows.map(a=>`<article class="card approval"><div><span class="badge ${a.status==='pending'?'warning':'success'}">${a.status==='pending'?'Pendiente':'Aprobada'}</span><h3>${a.type}</h3><p>${a.detail}</p><small>Solicitado por ${a.requester}</small></div><strong>${a.amount?money(a.amount):''}</strong>${a.status==='pending'?`<div class="approval-actions"><button class="btn secondary" onclick="resolveApproval('${a.id}','rejected')">Rechazar</button><button class="btn primary" onclick="resolveApproval('${a.id}','approved')">Autorizar</button></div>`:'<span class="badge success">Resuelta</span>'}</article>`).join('')}</div>`}
function reportsPage(){const d=data();return `${pageHead('Reportes','Análisis de desempeño y exportaciones.',`<button class="btn secondary">Exportar PDF</button><button class="btn primary">Exportar Excel</button>`)}<div class="report-grid"><section class="card"><div class="card-head"><div><h3>Mezcla de ventas</h3><p>Por categoría</p></div></div><div class="donut-wrap"><div class="donut"></div><div>${d.categorySales.map(x=>`<div class="legend"><span></span><b>${x.name}</b><em>${x.value}%</em></div>`).join('')}</div></div></section><section class="card"><div class="card-head"><div><h3>Indicadores comerciales</h3><p>Periodo actual</p></div></div><div class="report-stats"><div><small>Ticket promedio</small><strong>${money(d.metrics.revenue/Math.max(1,d.sales.length))}</strong></div><div><small>Margen</small><strong>${pct(d.metrics.margin)}</strong></div><div><small>Crecimiento</small><strong>+${pct(d.metrics.monthGrowth)}</strong></div><div><small>Cartera</small><strong>${money(d.metrics.receivable)}</strong></div></div></section></div><section class="card report-list"><h3>Reportes disponibles</h3>${[['Ventas y utilidad','Detalle por periodo, vendedor, sucursal y cliente.'],['Inventario y rotación','Existencias, mínimos, valor y productos críticos.'],['Cartera y cobranza','Saldos, antigüedad y clientes vencidos.'],['Compras y proveedores','Órdenes, recepción, gasto y saldos.'],['Rendimiento por sucursal','Ingresos, margen y participación por ubicación.']].map(x=>`<button><div><strong>${x[0]}</strong><small>${x[1]}</small></div><span>Generar →</span></button>`).join('')}</section>`}
function usersPage(){const db=loadDB(),c=currentCompany();return `${pageHead('Equipo','Usuarios, roles y accesos.',`<button class="btn primary" onclick="openModal('user')">＋ Agregar usuario</button>`)}<section class="card table-card"><div class="table-wrap"><table><thead><tr><th>Usuario</th><th>Correo</th><th>Rol</th><th>Estado</th></tr></thead><tbody>${c.members.map(m=>{const u=db.users.find(x=>x.id===m.userId),r=c.roles.find(x=>x.id===m.roleId);return `<tr><td><div class="user-cell"><span>${initials(u?.name)}</span><strong>${u?.name||'Usuario'}</strong></div></td><td>${u?.email||'—'}</td><td>${r?.name||'—'}</td><td><span class="badge success">Activo</span></td></tr>`}).join('')}</tbody></table></div></section>`}
function branchesPage(){const c=currentCompany();return `${pageHead('Sucursales','Ubicaciones operativas de la empresa.',`<button class="btn primary" onclick="openModal('branch')">＋ Nueva sucursal</button>`)}<div class="cards-grid">${c.branches.map((b,i)=>`<article class="entity-card branch"><div class="entity-head"><span class="entity-avatar branch">⌖</span><div><h3>${b.name}</h3><small>${b.city||'Sin ciudad'}</small></div><span class="badge success">Activa</span></div><div class="entity-metrics"><div><small>Ventas mes</small><strong>${money(data().branchSales[i]?.value||0)}</strong></div><div><small>Participación</small><strong>${pct((data().branchSales[i]?.value||0)/data().metrics.revenue*100)}</strong></div></div><div class="entity-foot"><span>${b.address||'Sin dirección'}</span><b>Configurar →</b></div></article>`).join('')}</div>`}
function auditPage(){return `${pageHead('Actividad','Bitácora de acciones relevantes.','')}<section class="card timeline">${data().audit.map(a=>`<article><span>${initials(a.user)}</span><div><strong>${a.action}</strong><p>${a.detail}</p><small>${a.user} · ${fmtDate(a.at)}</small></div></article>`).join('')}</section>`}
function rolesPage(){const c=currentCompany();return `${pageHead('Roles y permisos','Define exactamente qué puede hacer cada perfil.',`<button class="btn primary" onclick="openModal('role')">＋ Nuevo rol</button>`)}<div class="role-grid">${c.roles.map(r=>`<article class="card role-card"><div class="role-title"><div><h3>${r.name}</h3><small>${r.system?'Rol del sistema':'Personalizado'}</small></div><strong>${r.permissions.length}</strong></div><div class="perm-tags">${r.permissions.slice(0,8).map(p=>`<span>${p}</span>`).join('')}${r.permissions.length>8?`<span>+${r.permissions.length-8}</span>`:''}</div></article>`).join('')}</div>`}
function settingsPage(){const c=currentCompany();return `${pageHead('Configuración','Datos generales, operación y experiencia.','')}<div class="settings-grid"><form id="settingsForm" class="card settings-card"><h3>Información de la empresa</h3><label>Nombre comercial<input name="name" value="${esc(c.name)}"></label><label>Razón social<input name="legalName" value="${esc(c.legalName||'')}"></label><div class="two"><label>RFC<input name="rfc" value="${esc(c.rfc||'')}"></label><label>IVA %<input name="tax" type="number" value="${c.tax||16}"></label></div><button class="btn primary">Guardar cambios</button></form><section class="card settings-card"><h3>Experiencia</h3><div class="setting-row"><div><strong>Persistencia</strong><small>Los cambios viven solo en memoria y se reinician al recargar.</small></div><span class="badge info">Sesión actual</span></div><div class="setting-row"><div><strong>Módulos</strong><small>Ventas, inventario, finanzas, equipo y más.</small></div><button class="tiny">Configurar</button></div><div class="setting-row"><div><strong>Respaldo</strong><small>Descarga todos los datos locales.</small></div><button class="tiny" onclick="downloadSnapshot()">Descargar</button></div></section></div>`}

function renderNotifications(){const n=data().notifications;return `<div class="drawer-back" onclick="if(event.target===this){ui.notifs=false;renderApp()}"><aside class="drawer"><header><div><h3>Notificaciones</h3><p>${n.filter(x=>!x.read).length} sin leer</p></div><button onclick="ui.notifs=false;renderApp()">×</button></header>${n.map(x=>`<article onclick="readNotif('${x.id}','${x.action||''}')" class="${x.read?'read':''}"><span class="notif-icon ${x.type}">•</span><div><strong>${x.title}</strong><p>${x.text}</p><small>${fmtShort(x.at)}</small></div></article>`).join('')}</aside></div>`}
function readNotif(id,action){mutate(c=>{const n=c.data.notifications.find(x=>x.id===id);if(n)n.read=true});ui.notifs=false;if(action)ui.route=action;renderApp()}
function renderCommand(){const items=NAV.flatMap(x=>x[1]).filter(x=>can(x[0]));return `<div class="command-back" onclick="if(event.target===this){ui.command=false;renderApp()}"><div class="command"><input autofocus placeholder="Busca módulos o acciones…" oninput="commandFilter(this.value)"><div id="commandResults">${commandItems(items)}</div></div></div>`}
function commandItems(items,q=''){const acts=[...items.map(x=>[x[0],x[1],`go('${x[0]}')`]),['new-sale','Nueva venta',"openModal('sale')"],['new-client','Nuevo cliente',"openModal('customer')"],['new-task','Nueva tarea',"openModal('task')"]];return acts.filter(x=>x[1].toLowerCase().includes(q.toLowerCase())).map(x=>`<button onclick="${x[2]}"><span>${x[1]}</span><kbd>↵</kbd></button>`).join('')||'<div class="empty-mini">Sin resultados</div>'}
function commandFilter(q){document.getElementById('commandResults').innerHTML=commandItems(NAV.flatMap(x=>x[1]).filter(x=>can(x[0])),q)}

function openModal(type){if(type==='sale')ui.saleLines=[{productId:'',quantity:1}];ui.modal={type};ui.command=false;renderApp()}
function addSaleLine(){ui.saleLines.push({productId:'',quantity:1});renderApp()}
function removeSaleLine(index){if(ui.saleLines.length>1)ui.saleLines.splice(index,1);renderApp()}
function updateSaleLine(index,field,value){if(!ui.saleLines[index])return;ui.saleLines[index][field]=field==='quantity'?Math.max(1,Math.floor(Number(value)||1)):value;renderSaleTotals()}
function saleLineProductOptions(selected=''){return `<option value="">Selecciona un producto</option>${data().products.filter(p=>p.type!=='Servicio'||true).map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.name)} · ${money(p.price)}${p.type==='Producto'?` · Stock ${p.stock}`:' · Servicio'}</option>`).join('')}`}
function renderSaleTotals(){const form=document.getElementById('saleForm');if(!form)return;const lines=ui.saleLines.map((l,i)=>{const p=data().products.find(x=>x.id===l.productId);return {p,quantity:Number(l.quantity)||1,total:(p?.price||0)*(Number(l.quantity)||1)}});const total=lines.reduce((a,l)=>a+l.total,0);const totalEl=form.querySelector('[data-sale-total]');if(totalEl)totalEl.textContent=money(total);const pay=form.querySelector('[name="paymentAmount"]');const paid=Number(pay?.value)||0;const balance=form.querySelector('[data-sale-balance]');if(balance)balance.textContent=money(Math.max(0,total-paid));}
function closeModal(){ui.modal=null;renderApp()}
function formFields(arr){return arr.map(([n,l,t='text'])=>`<label>${l}<input name="${n}" type="${t}" ${t==='number'?'step="0.01"':''} required></label>`).join('')}
function renderModal(){const t=ui.modal.type,d=data();if(t==='customerView'){const c=d.customers.find(x=>x.id===ui.modal.id);return `<div class="modal-back" onclick="if(event.target===this)closeModal()"><div class="modal detail-modal"><header><div><span class="entity-avatar">${initials(c.name)}</span><div><h2>${c.name}</h2><p>${c.rfc} · ${c.email}</p></div></div><button onclick="closeModal()">×</button></header><div class="detail-kpis">${kpi('Saldo',money(c.balance))}${kpi('Ventas',money(c.sales))}${kpi('Límite',money(c.creditLimit))}${kpi('Crédito',`${c.daysCredit} días`)}</div><div class="tabs"><button class="active">Resumen</button><button>Ventas</button><button>Cobranza</button><button>Actividad</button></div><div class="detail-body"><section><h3>Información comercial</h3><p><b>Vendedor:</b> ${c.seller}</p><p><b>Teléfono:</b> ${c.phone}</p><p><b>Última compra:</b> ${fmtDate(c.lastPurchase)}</p></section><section><h3>Estado de cuenta</h3><div class="statement"><span>Saldo actual</span><strong>${money(c.balance)}</strong></div><button class="btn secondary">Generar estado de cuenta</button></section></div></div></div>`}
if(t==='productView'){const p=d.products.find(x=>x.id===ui.modal.id);return `<div class="modal-back" onclick="if(event.target===this)closeModal()"><div class="modal detail-modal"><header><div><span class="entity-avatar supplier">${p.type==='Servicio'?'S':'P'}</span><div><h2>${p.name}</h2><p>${p.sku} · ${p.category}</p></div></div><button onclick="closeModal()">×</button></header><div class="detail-kpis">${kpi('Precio',money(p.price))}${kpi('Costo',money(p.cost))}${kpi('Margen',p.cost?pct((p.price-p.cost)/p.price*100):'100%')}${kpi('Existencia',p.type==='Producto'?p.stock:'—')}</div><div class="tabs"><button class="active">Resumen</button><button>Inventario</button><button>Compras</button><button>Ventas</button></div><div class="detail-body"><section><h3>Inventario</h3><p><b>Disponible:</b> ${p.stock}</p><p><b>Comprometido:</b> ${p.reserved||0}</p><p><b>En camino:</b> ${p.incoming||0}</p></section><section><h3>Niveles</h3><p><b>Mínimo:</b> ${p.minStock}</p><p><b>Máximo:</b> ${p.maxStock}</p><div class="progress"><i style="width:${Math.min(100,p.stock/p.maxStock*100)}%"></i></div></section></div></div></div>`}
if(t==='stockAdjustment'||t==='stockCount'){const products=d.products.filter(p=>p.type==='Producto');const selected=ui.modal.productId||products[0]?.id||'';return `<div class="modal-back" onclick="if(event.target===this)closeModal()"><div class="modal stock-modal"><header><div><h2>${t==='stockCount'?'Conteo físico':'Movimiento de inventario'}</h2><p>${t==='stockCount'?'Registra la cantidad real contada; se generará el ajuste.':'Registra una entrada, salida o corrección de existencias.'}</p></div><button type="button" onclick="closeModal()">×</button></header><form id="modalForm" class="modal-form"><input type="hidden" name="inventoryAction" value="${t}"><label>Producto<select name="productId" required>${products.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.name)} · Existencia: ${p.stock}</option>`).join('')}</select></label>${t==='stockCount'?'<label>Cantidad física contada<input name="countedStock" type="number" min="0" step="1" required></label>':'<label>Tipo de movimiento<select name="movementType" required><option value="in">Entrada</option><option value="out">Salida</option><option value="adjustment">Ajuste (cantidad final)</option></select></label><label>Cantidad<input name="quantity" type="number" min="0" step="1" required></label>'}<label>Motivo<input name="reason" required maxlength="160" placeholder="Ej. Compra, merma, conteo…"></label><label>Referencia (opcional)<input name="reference" maxlength="80" placeholder="Factura, nota o folio"></label><p class="form-hint">El movimiento quedará registrado en el historial del inventario.</p><footer><button type="button" class="btn secondary" onclick="closeModal()">Cancelar</button><button class="btn primary" type="submit">Guardar movimiento</button></footer></form></div></div>`}
if(t==='sale'){const customers=d.customers.filter(c=>c.status!=='Inactivo');return `<div class="modal-back" onclick="if(event.target===this)closeModal()"><div class="modal sale-modal"><header><div><h2>Nueva venta</h2><p>El inventario y la cobranza se actualizarán al confirmar.</p></div><button type="button" onclick="closeModal()">×</button></header><form id="saleForm" class="modal-form"><label>Cliente<select name="customerId" required><option value="">Selecciona un cliente</option>${customers.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><div class="sale-lines-head"><strong>Productos / servicios</strong><button type="button" class="btn secondary small" onclick="addSaleLine()">＋ Agregar partida</button></div><div class="sale-lines">${ui.saleLines.map((l,i)=>`<div class="sale-line"><label>Producto<select required name="product_${i}" onchange="updateSaleLine(${i},'productId',this.value)">${saleLineProductOptions(l.productId)}</select></label><label class="sale-qty">Cantidad<input type="number" min="1" step="1" value="${l.quantity}" required onchange="updateSaleLine(${i},'quantity',this.value)" oninput="updateSaleLine(${i},'quantity',this.value)"></label>${ui.saleLines.length>1?`<button type="button" class="btn secondary small" onclick="removeSaleLine(${i})" aria-label="Quitar partida">×</button>`:''}</div>`).join('')}</div><label>Concepto (opcional)<input name="concept" placeholder="Ej. Pedido de productos de limpieza"></label><div class="sale-total-row"><span>Total de venta</span><strong data-sale-total>${money(ui.saleLines.reduce((sum,l)=>{const p=d.products.find(x=>x.id===l.productId);return sum+(p?.price||0)*(Number(l.quantity)||1)},0))}</strong></div><div class="sale-payment-grid"><label>Importe recibido<input name="paymentAmount" type="number" min="0" step="0.01" value="0" required oninput="renderSaleTotals()"></label><label>Método de pago<select name="paymentMethod"><option value="cash">Efectivo</option><option value="transfer">Transferencia</option><option value="card">Tarjeta</option><option value="other">Otro</option></select></label></div><p class="sale-balance">Saldo pendiente: <strong data-sale-balance>${money(0)}</strong></p><p class="form-hint">Prototipo local: los datos se guardan en este navegador, no en un servidor.</p><footer><button type="button" class="btn secondary" onclick="closeModal()">Cancelar</button><button class="btn primary" type="submit">Confirmar venta</button></footer></form></div></div>`}
const cfg={customer:['Nuevo cliente',formFields([['name','Nombre / razón social'],['rfc','RFC'],['email','Correo','email'],['phone','Teléfono'],['balance','Saldo inicial','number']])],supplier:['Nuevo proveedor',formFields([['name','Nombre / razón social'],['rfc','RFC'],['email','Correo','email'],['phone','Teléfono'],['balance','Saldo inicial','number']])],product:['Nuevo producto o servicio',formFields([['name','Nombre'],['sku','SKU'],['price','Precio','number'],['cost','Costo','number'],['stock','Existencia','number'],['minStock','Stock mínimo','number']])],sale:['Nueva venta',formFields([['customer','Cliente'],['concept','Concepto'],['total','Total','number']])],quote:['Nueva cotización',formFields([['customer','Cliente'],['concept','Concepto'],['total','Total','number']])],order:['Nuevo pedido',formFields([['customer','Cliente'],['concept','Concepto'],['total','Total','number']])],purchase:['Nueva compra',formFields([['supplier','Proveedor'],['concept','Concepto'],['total','Total','number']])],task:['Nueva tarea',formFields([['title','Tarea'],['assignee','Responsable']])],transaction:['Nuevo movimiento',formFields([['concept','Concepto'],['amount','Importe','number']])],account:['Nueva cuenta',formFields([['name','Nombre'],['balance','Saldo inicial','number']])],branch:['Nueva sucursal',formFields([['name','Nombre'],['city','Ciudad'],['address','Dirección']])],user:['Agregar usuario',formFields([['name','Nombre'],['email','Correo','email'],['password','Contraseña temporal','password']])],role:['Nuevo rol',formFields([['name','Nombre del rol']])]}[t];return `<div class="modal-back" onclick="if(event.target===this)closeModal()"><div class="modal"><header><h2>${cfg?.[0]||'Crear'}</h2><button onclick="closeModal()">×</button></header><form id="modalForm" class="modal-form">${cfg?.[1]||''}${t==='user'?`<label>Rol<select name="roleId">${currentCompany().roles.map(r=>`<option value="${r.id}">${r.name}</option>`).join('')}</select></label>`:''}${t==='role'?`<div class="perm-grid">${PERMISSIONS.map(p=>`<label><input type="checkbox" name="perm" value="${p}"> ${p}</label>`).join('')}</div>`:''}<footer><button type="button" class="btn secondary" onclick="closeModal()">Cancelar</button><button class="btn primary">Guardar</button></footer></form></div></div>`}

async function modalSubmit(f){const t=ui.modal.type,o=Object.fromEntries(f);if(t==='stockAdjustment'||t==='stockCount'){const product=data().products.find(p=>p.id===o.productId);if(!product){alert('Selecciona un producto válido.');return}let delta=0,after=Number(product.stock)||0,kind=o.movementType||'count';if(t==='stockCount'){const counted=Number(o.countedStock);if(!Number.isInteger(counted)||counted<0){alert('La cantidad contada debe ser un entero igual o mayor que cero.');return}after=counted;delta=after-(Number(product.stock)||0);kind='count'}else{const qty=Number(o.quantity);if(!Number.isInteger(qty)||qty<0){alert('La cantidad debe ser un entero igual o mayor que cero.');return}if(kind==='in'){delta=qty;after+=qty}else if(kind==='out'){delta=-qty;after-=qty}else{after=qty;delta=after-(Number(product.stock)||0)}if(after<0){alert('No hay existencias suficientes para registrar esa salida.');return}}const before=Number(product.stock)||0;mutate(c=>{const d=c.data;const p=d.products.find(x=>x.id===o.productId);p.stock=after;(d.inventoryMovements||(d.inventoryMovements=[])).unshift({id:uid('mov'),productId:p.id,product:p.name,type:kind,quantity:delta,before,after,reason:String(o.reason||'').trim(),reference:String(o.reference||'').trim(),at:nowISO(),user:currentUser()?.name||'Usuario'});d.inventoryMovements=d.inventoryMovements.slice(0,1000);d.metrics=d.metrics||{};d.metrics.inventoryValue=Number(d.metrics.inventoryValue||0)+delta*Number(p.cost||0);d.audit.unshift({id:uid('aud'),at:nowISO(),user:currentUser()?.name||'Usuario',action:t==='stockCount'?'Conteo físico registrado':'Movimiento de inventario',detail:`${p.name}: ${before} → ${after} (${o.reason})`})});ui.modal=null;ui.route='inventory';toast(`Inventario actualizado: ${before} → ${after}`);return}mutate((c,db)=>{const d=c.data;const add=(arr,rec)=>{d[arr].unshift({id:uid(arr),createdAt:nowISO(),...rec})};if(t==='customer')add('customers',{...o,balance:+o.balance||0,creditLimit:0,daysCredit:0,sales:0,lastPurchase:nowISO(),seller:currentUser().name,status:'Activo'});if(t==='supplier')add('suppliers',{...o,balance:+o.balance||0,lastPurchase:nowISO()});if(t==='product')add('products',{...o,type:'Producto',category:'General',price:+o.price||0,cost:+o.cost||0,stock:+o.stock||0,minStock:+o.minStock||0,maxStock:100,reserved:0,incoming:0});if(t==='quote')add('quotes',{folio:`CT-${String(d.quotes.length+49).padStart(5,'0')}`,...o,total:+o.total,status:'draft',validUntil:new Date(Date.now()+7*86400000).toISOString()});if(t==='order')add('orders',{folio:`PD-${String(d.orders.length+32).padStart(5,'0')}`,...o,total:+o.total,status:'preparing'});if(t==='purchase')add('purchases',{folio:`OC-${String(d.purchases.length+78).padStart(5,'0')}`,...o,total:+o.total,status:'draft',expected:new Date(Date.now()+5*86400000).toISOString()});if(t==='task')add('tasks',{...o,priority:'Normal',status:'pending',due:new Date(Date.now()+2*86400000).toISOString()});if(t==='transaction'){const acc=d.accounts[0];add('transactions',{concept:o.concept,amount:+o.amount,kind:'income',accountId:acc?.id,at:nowISO()});if(acc)acc.balance+=+o.amount}if(t==='account')d.accounts.push({id:uid('acc'),name:o.name,type:'bank',balance:+o.balance||0});if(t==='branch')c.branches.push({id:uid('br'),...o,active:true});});if(t==='user'){const db=loadDB(),c=db.companies.find(x=>x.id===getSession().companyId);if(db.users.some(u=>u.email===o.email.toLowerCase()))return alert('Ese correo ya existe');const nu={id:uid('usr'),name:o.name,email:o.email.toLowerCase(),passwordHash:await hashPassword(o.password),companyIds:[c.id],createdAt:nowISO()};db.users.push(nu);c.members.push({userId:nu.id,roleId:o.roleId,status:'active'});saveDB(db)}if(t==='role'){mutate(c=>c.roles.push({id:uid('role'),name:o.name,permissions:[...f.getAll('perm')],system:false}))}audit('Registro creado',t);ui.modal=null;toast('Guardado correctamente')}
function confirmSale(formData){
  const fd=Object.fromEntries(formData);const customer=data().customers.find(c=>c.id===fd.customerId);if(!customer){alert('Selecciona un cliente.');return}
  const lines=ui.saleLines.map((line,i)=>{const product=data().products.find(p=>p.id===fd[`product_${i}`]||p.id===line.productId);const quantity=Math.floor(Number(line.quantity)||0);return {product,quantity}});
  if(!lines.length||lines.some(x=>!x.product||x.quantity<1)){alert('Revisa los productos y cantidades.');return}
  const requested=new Map();for(const line of lines){if(line.product.type==='Producto')requested.set(line.product.id,(requested.get(line.product.id)||0)+line.quantity)}for(const [productId,quantity] of requested){const product=data().products.find(p=>p.id===productId);if(Number(product.stock)<quantity){alert(`Existencia insuficiente de ${product.name}. Disponible: ${product.stock}; solicitada: ${quantity}.`);return}}
  const total=lines.reduce((sum,line)=>sum+Number(line.product.price||0)*line.quantity,0);const payment=Number(fd.paymentAmount);
  if(!Number.isFinite(payment)||payment<0||payment>total){alert('El importe recibido debe estar entre $0 y el total de la venta.');return}
  const now=nowISO();const saleId=uid('sale');const folio=`VT-${String(Math.max(0,...data().sales.map(s=>Number(String(s.folio||'').split('-').pop())||0))+1).padStart(5,'0')}`;
  try{mutate((c)=>{const d=c.data;const sale={id:saleId,folio,customer:customer.name,customerId:customer.id,concept:String(fd.concept||'').trim()||lines.map(l=>l.product.name).join(', '),items:lines.map(l=>({productId:l.product.id,sku:l.product.sku,name:l.product.name,quantity:l.quantity,unitPrice:Number(l.product.price||0),unitCost:Number(l.product.cost||0),lineTotal:Number(l.product.price||0)*l.quantity})),total,paid:payment,balance:total-payment,status:'confirmed',paymentStatus:payment>=total?'paid':payment>0?'partial':'pending',paymentMethod:fd.paymentMethod||'cash',seller:currentUser()?.name||'Usuario',branch:c.branches.find(b=>b.name===ui.branch)?.name||c.branches[0]?.name||'Principal',createdAt:now};
    // Todas las validaciones se realizan antes de mutar stock, saldo o caja.
    for(const line of lines){if(line.product.type==='Producto'){const p=d.products.find(x=>x.id===line.product.id);p.stock=Number(p.stock)-line.quantity;(d.inventoryMovements||(d.inventoryMovements=[])).unshift({id:uid('mov'),productId:p.id,product:p.name,type:'sale',quantity:-line.quantity,reference:folio,at:now,user:currentUser()?.name||'Usuario'});}}
    d.sales.unshift(sale);customer.balance=Number(customer.balance||0)+sale.balance;customer.sales=Number(customer.sales||0)+total;customer.lastPurchase=now;
    if(payment>0){const account=d.accounts.find(a=>a.type==='cash')||d.accounts[0];if(account)account.balance=Number(account.balance||0)+payment;d.transactions.unshift({id:uid('tx'),concept:`Cobro ${folio} · ${customer.name}`,kind:'income',amount:payment,accountId:account?.id,at:now,saleId,method:sale.paymentMethod});(d.payments||(d.payments=[])).unshift({id:uid('pay'),saleId,folio,customerId:customer.id,amount:payment,method:sale.paymentMethod,at:now});}
    d.metrics=d.metrics||{};d.metrics.revenue=Number(d.metrics.revenue||0)+total;d.metrics.receivable=Number(d.metrics.receivable||0)+sale.balance;d.metrics.inventoryValue=Number(d.metrics.inventoryValue||0)-lines.reduce((sum,l)=>sum+(l.product.type==='Producto'?Number(l.product.cost||0)*l.quantity:0),0);
    const branch=d.branchSales?.find(b=>b.name===sale.branch);if(branch)branch.value=Number(branch.value||0)+total;
    d.audit.unshift({id:uid('aud'),at:now,user:sale.seller,action:'Venta confirmada',detail:`${folio} · ${customer.name} · ${money(total)}`});d.audit=d.audit.slice(0,100);
  });saveDB(loadDB());ui.modal=null;ui.saleLines=[{productId:'',quantity:1}];ui.route='sales';toast(`Venta ${folio} registrada`);
  }catch(err){console.error(err);alert('No se pudo completar la venta. No uses este prototipo para operaciones reales; revisa los datos y vuelve a intentarlo.')}}
function convertQuote(id){mutate(c=>{const q=c.data.quotes.find(x=>x.id===id);if(!q)return;c.data.orders.unshift({id:uid('order'),folio:`PD-${String(c.data.orders.length+32).padStart(5,'0')}`,customer:q.customer,concept:q.concept,total:q.total,status:'preparing',createdAt:nowISO()});q.status='accepted'});notify('Pedido creado','La cotización fue convertida en pedido.','success','orders');audit('Cotización convertida','Pedido creado');toast('Pedido creado')}
function completeTask(id){mutate(c=>{const t=c.data.tasks.find(x=>x.id===id);if(t)t.status='done'});audit('Tarea completada',id);toast('Tarea completada')}
function resolveApproval(id,statusx){mutate(c=>{const a=c.data.approvals.find(x=>x.id===id);if(a)a.status=statusx});audit(statusx==='approved'?'Autorización aprobada':'Autorización rechazada',id);toast(statusx==='approved'?'Autorizado':'Rechazado')}
function exportCSV(type){const rows=type==='inventoryMovements'?(data().inventoryMovements||[]):(data()[type]||[]);if(!rows.length)return toast('No hay datos');const keys=[...new Set(rows.flatMap(Object.keys))];const csv=[keys.join(','),...rows.map(r=>keys.map(k=>`"${String(r[k]??'').replace(/"/g,'""')}"`).join(','))].join('\n');download(`${type}.csv`,csv,'text/csv')}
function downloadSnapshot(){download(`cia-sesion.json`,JSON.stringify(loadDB(),null,2),'application/json')}
function download(name,text,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function bindCharts(){if(ui.route!=='dashboard')return;const el=document.getElementById('lineChart');if(!el)return;const vals=data().trend||[];const max=Math.max(...vals,1),min=Math.min(...vals,0);const pts=vals.map((v,i)=>`${i/(vals.length-1||1)*100},${88-(v-min)/(max-min||1)*65}`).join(' ');el.innerHTML=`<svg viewBox="0 0 100 100" preserveAspectRatio="none"><defs><linearGradient id="g" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#2f6df6" stop-opacity=".25"/><stop offset="100%" stop-color="#2f6df6" stop-opacity="0"/></linearGradient></defs><polygon points="0,100 ${pts} 100,100" fill="url(#g)"/><polyline points="${pts}" fill="none" stroke="#2f6df6" stroke-width="2.2" vector-effect="non-scaling-stroke"/></svg><div class="chart-labels">${['Mar','Abr','May','Jun','Jul','Ago','Sep'].map(x=>`<span>${x}</span>`).join('')}</div>`}

document.addEventListener('submit',async e=>{if(e.target.id==='saleForm'){e.preventDefault();confirmSale(new FormData(e.target));return}if(e.target.id==='modalForm'){e.preventDefault();await modalSubmit(new FormData(e.target))}if(e.target.id==='settingsForm'){e.preventDefault();const f=Object.fromEntries(new FormData(e.target));mutate(c=>Object.assign(c,{...f,tax:+f.tax||16}));audit('Configuración actualizada','Datos de empresa');toast('Configuración guardada')}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(currentUser()){ui.command=true;renderApp()}}if(e.key==='Escape'){ui.command=false;ui.notifs=false;ui.modal=null;if(currentUser())renderApp()}});
window.addEventListener('hashchange',render);
render();

window.NAV=NAV;
